content:
Below is a clean Terraform implementation that creates reusable modules for:

- **S3 bucket** with versioning, encryption, and public access blocked
- **RDS PostgreSQL** with deletion protection, backups, and no public access
- **IAM role for service accounts** with least-privilege support

It supports **dev/prod** via **tfvars** and can also be adapted to **workspaces**.

---

# Suggested repo structure

```text
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── providers.tf
├── versions.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3_bucket/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds_postgres/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam_service_account_role/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

# Root module

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

## `providers.tf`

```hcl
provider "aws" {
  region = var.aws_region
}
```

## `variables.tf`

```hcl
variable "aws_region" {
  type = string
}

variable "environment" {
  type = string
}

variable "project_name" {
  type = string
}

variable "tags" {
  type    = map(string)
  default = {}
}

# S3
variable "bucket_name" {
  type = string
}

variable "bucket_encryption_algorithm" {
  type    = string
  default = "AES256"
}

variable "enable_replication" {
  type    = bool
  default = false
}

variable "replication_destination_bucket_arn" {
  type    = string
  default = null
}

variable "replication_destination_kms_key_arn" {
  type    = string
  default = null
}

# RDS
variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "db_instance_class" {
  type = string
}

variable "db_allocated_storage" {
  type    = number
  default = 20
}

variable "db_engine_version" {
  type    = string
  default = "15.7"
}

variable "db_backup_retention_period" {
  type    = number
  default = 7
}

variable "db_multi_az" {
  type    = bool
  default = false
}

variable "db_storage_encrypted" {
  type    = bool
  default = true
}

variable "db_subnet_ids" {
  type = list(string)
}

variable "db_vpc_security_group_ids" {
  type = list(string)
}

# IAM service account role
variable "oidc_provider_arn" {
  type = string
}

variable "oidc_provider_url" {
  type = string
}

variable "k8s_namespace" {
  type = string
}

variable "k8s_service_account_name" {
  type = string
}

variable "service_account_policy_json" {
  type = string
}
```

## `main.tf`

```hcl
locals {
  common_tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

module "assets_bucket" {
  source = "./modules/s3_bucket"

  bucket_name                          = var.bucket_name
  encryption_algorithm                 = var.bucket_encryption_algorithm
  tags                                 = local.common_tags
  enable_replication                   = var.enable_replication
  replication_destination_bucket_arn   = var.replication_destination_bucket_arn
  replication_destination_kms_key_arn  = var.replication_destination_kms_key_arn
}

module "postgres" {
  source = "./modules/rds_postgres"

  identifier                 = "${var.project_name}-${var.environment}-postgres"
  db_name                    = var.db_name
  username                   = var.db_username
  password                   = var.db_password
  instance_class             = var.db_instance_class
  allocated_storage          = var.db_allocated_storage
  engine_version             = var.db_engine_version
  backup_retention_period    = var.db_backup_retention_period
  multi_az                   = var.db_multi_az
  storage_encrypted          = var.db_storage_encrypted
  subnet_ids                 = var.db_subnet_ids
  vpc_security_group_ids     = var.db_vpc_security_group_ids
  tags                       = local.common_tags
}

module "service_account_role" {
  source = "./modules/iam_service_account_role"

  role_name                  = "${var.project_name}-${var.environment}-sa-role"
  oidc_provider_arn          = var.oidc_provider_arn
  oidc_provider_url          = var.oidc_provider_url
  k8s_namespace              = var.k8s_namespace
  k8s_service_account_name   = var.k8s_service_account_name
  policy_json                = var.service_account_policy_json
  tags                       = local.common_tags
}
```

## `outputs.tf`

```hcl
output "bucket_id" {
  value = module.assets_bucket.bucket_id
}

output "bucket_arn" {
  value = module.assets_bucket.bucket_arn
}

output "db_instance_endpoint" {
  value = module.postgres.db_instance_endpoint
}

output "db_instance_arn" {
  value = module.postgres.db_instance_arn
}

output "service_account_role_arn" {
  value = module.service_account_role.role_arn
}
```

