# Module: IAM role for service accounts

This module creates an **IRSA-style role** for EKS service accounts using OIDC trust.

## `modules/iam_service_account_role/variables.tf`

```hcl
variable "role_name" {
  type = string
}

variable "oidc_provider_arn" {
  type = string
}

variable "oidc_provider_url" {
  type = string
}

variable "k8s_namespace" {
  type = string
}

variable "k8s_service_account_name" {
  type = string
}

variable "policy_json" {
  type = string
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

## `modules/iam_service_account_role/main.tf`

```hcl
locals {
  oidc_subject = "system:serviceaccount:${var.k8s_namespace}:${var.k8s_service_account_name}"
  oidc_url_hostpath = replace(var.oidc_provider_url, "https://", "")
}

resource "aws_iam_role" "this" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${local.oidc_url_hostpath}:sub" = local.oidc_subject
            "${local.oidc_url_hostpath}:aud" = "sts.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "this" {
  name   = "${var.role_name}-policy"
  policy = var.policy_json
}

resource "aws_iam_role_policy_attachment" "this" {
  role       = aws_iam_role.this.name
  policy_arn = aws_iam_policy.this.arn
}
```

## `modules/iam_service_account_role/outputs.tf`

```hcl
output "role_arn" {
  value = aws_iam_role.this.arn
}

output "role_name" {
  value = aws_iam_role.this.name
}
```

